mapper.select:
/* userLogin - Lee JiSeob */ SELECT USER_ID ,C##RG.DEC_B64(FLNM_ENCPT) AS FLNM_ENCPT ,BIRTHDATE ,GENDER ,C##RG.DEC_B64(EMAIL) AS EMAIL ,C##RG.DEC_B64(MOBILE) AS MOBILE ,AGE ,MEMBER_TYPE ,CMMNS_CD_VALUE_NM || '/' || INST_NM || '/' || INST_NO || '/' || INST_TYPE_SE_CD || '/' || RPRS_TELNO AS AGENCY_CONTACTS ,INST_NO ,INST_NM ,UNT_TASKWK_SE_CD ,RGN_CD ,INST_TYPE_SE_CD ,RPRS_TELNO ,(SELECT MENU_NO FROM SAB200 /* 메뉴 */ WHERE MENU_NM = CMMNS_CD_VALUE_NM AND MENU_LEVELA_NO = 1) AS TOP_MENU_NO ,ENFSN_NO ,USER_INST_NO ,YNGBGS_PRTCR_NO ,INDV_IDNTFC_NO ,WRD_TELNO ,CASE WHEN PST_ADDR IS NULL THEN '' ELSE SUBSTR(PST_ADDR, 1, INSTR(PST_ADDR, ' ') - 1) END AS SIDO_NM ,CASE WHEN PST_ADDR IS NULL OR SUBSTR(PST_ADDR, 1, 2) = '세종' THEN '' ELSE SUBSTR(PST_ADDR, INSTR(PST_ADDR, ' ') + 1, INSTR(PST_ADDR, ' ', INSTR(PST_ADDR, ' ') + 1) - INSTR(PST_ADDR, ' ') - 1) END AS SIGUNGU_NM ,DEPT_CD ,DEPT_NM ,GROUP_AUTHRT_SE_CD ,AUTHRT_SE_CD FROM ( SELECT C.USER_ID, D.FLNM_ENCPT AS FLNM_ENCPT, D.BRTH_YMD AS BIRTHDATE, D.SXDC_SE_CD AS GENDER, D.EML_ADDR_ENCPT AS EMAIL, D.MBL_TELNO_ENCPT AS MOBILE, TO_CHAR(TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')) - TO_NUMBER(SUBSTR(D.BRTH_YMD, 1, 4)) + 1) AS AGE, '종사자' AS MEMBER_TYPE, (SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND CMMNS_CD_VALUE = F.UNT_TASKWK_SE_CD) AS CMMNS_CD_VALUE_NM, F.INST_NO, F.INST_NM, F.UNT_TASKWK_SE_CD, F.RGN_CD, F.INST_TYPE_SE_CD, F.RPRS_TELNO, C.ENFSN_NO AS ENFSN_NO, E.INST_NO AS USER_INST_NO, C.YNGBGS_PRTCR_NO AS YNGBGS_PRTCR_NO, C.INDV_IDNTFC_NO AS INDV_IDNTFC_NO, D.WRD_TELNO AS WRD_TELNO, (SELECT PST_ADDR FROM SCA300 /* 개인정보 */ WHERE INDV_IDNTFC_NO = D.INDV_IDNTFC_NO) AS PST_ADDR, D.OGDP_DEPT_CD AS DEPT_CD, G.DEPT_NM, E.GROUP_AUTHRT_SE_CD, /* 그룹권한구분코드 */ E.AUTHRT_SE_CD /* 권한구분코드 */ FROM SAA200 C /* 사용자 */ JOIN SCA100 D /* 종사자 */ ON D.ENFSN_NO = C.ENFSN_NO JOIN SAB230 E /* 사용자기관 */ ON E.USER_ID = C.USER_ID AND E.MAIST_YN = 'Y' JOIN SAA000 F /* 통합기관 */ ON F.INST_NO = E.INST_NO LEFT JOIN SAA300 G /* 기관부서 */ ON G.DEPT_CD = D.OGDP_DEPT_CD WHERE LOWER(C.USER_ID) = LOWER(#{id})
AND C.USER_PSWD_ENCPT = C##RG.HASH_B64(#{pass})
/* AND C.USER_ID_USE_SE_CD = '2' */ /* 승인 상태만 로그인 허용 */
/* AND NVL(C.USER_CNTN_INTRCP_YN, 'N') != 'Y' */ /* 차단 해제 상태만 로그인 허용 */
/* AND NVL(D.DEL_YN, 'N') = 'N' */ )

/* userLogin_backup - Lee JiSeob */
SELECT C.USER_ID, D.FLNM_ENCPT, D.OGDP_INST_NO, E.INST_NM, G.ENG_CTPV_NM, G.CTPV_NM, E.RGN_CD, G.SGG_NM FROM SAA200 C /* 사용자 */, SCA100 D /* 종사자 */ LEFT JOIN SAA000 E /* 기관코드 */ ON E.INST_NO = D.OGDP_INST_NO LEFT JOIN SAA020 G /* 시군구코드 */ ON G.SGG_CD = E.RGN_CD WHERE C.ENFSN_NO = D.ENFSN_NO AND C.USER_ID = #{id}
AND C.USER_PSWD_ENCPT = #{pass}
AND C.USER_ID_USE_SE_CD = '2' /* 승인 상태만 로그인 허용 */

mapper.update:
/* savePassword - Lee JiSeob */
UPDATE SAA200 /* 사용자 */
SET USER_PSWD_ENCPT = C##RG.HASH_B64(#{userPswdEncpt}), BFE_PSWD_ENCPT1 = #{bfePswdEncpt1}, LGN_ERR_CONT = 0, LAST_MDFR_ID = #{userId2}, LAST_MDFCN_DT = SYSDATE, PSWD_LAST_CHG_DT = SYSDATE
WHERE USER_ID = #{userId}

