/* selectCurrentPassword - Lee JiSeob */

SELECT
    COUNT(*)

FROM
    SAA200 /* 사용자 */

WHERE
    USER_ID = #{userId}
    AND USER_PSWD_ENCPT = #{currentPasswordEncpt}

mapper.update:


/* increaseLoginErrorCount - Lee JiSeob */

UPDATE SAA200 /* 사용자 */

SET LGN_ERR_CONT = NVL(LGN_ERR_CONT, 0) + 1

WHERE USER_ID = #{USER_ID}



/* resetLoginErrorCount - Lee JiSeob */

UPDATE SAA200 /* 사용자 */

SET LGN_ERR_CONT = 0

WHERE USER_ID = #{USER_ID}

mapper.select:


/* selectLoginErrorCount - Lee JiSeob */

SELECT 

    NVL(LGN_ERR_CONT, 0) AS LGN_ERR_CONT

FROM SAA200 /* 사용자 */

WHERE USER_ID = #{USER_ID}



/* selectPasswordMap - Lee JiSeob */

SELECT

    USER_PSWD_ENCPT AS CURR_PASSWORD,
    BFE_PSWD_ENCPT1 AS PREV_PASSWORD

FROM SAA200 /* 사용자 */

WHERE USER_ID = #{USER_ID}

mapper.update:


/* updatePasswordChangeDate - Lee JiSeob */

UPDATE SAA200 /* 사용자 */

SET PSWD_LAST_CHG_DT = SYSDATE

WHERE USER_ID = #{USER_ID}

mapper.select:


/* findIdPhone - Lee JiSeob */

SELECT
    USER_ID

FROM SAA200 C /* 사용자 */
LEFT JOIN SCA100 D /* 종사자 */ ON D.ENFSN_NO = C.ENFSN_NO
/* LEFT JOIN SAA000 E 통합기관 ON E.INST_NO = C.INST_NO */
LEFT JOIN SCA200 F /* 청소년보호자 */ ON F.YNGBGS_PRTCR_NO = C.YNGBGS_PRTCR_NO

WHERE
    (
    (D.FLNM_ENCPT = C##RG.ENC_B64(#{name}) AND (
        D.MBL_TELNO_ENCPT = C##RG.ENC_B64(#{phone1}) OR
        D.MBL_TELNO_ENCPT = C##RG.ENC_B64(#{phone2})
    )
    )

    OR
    (F.FLNM_ENCPT = C##RG.ENC_B64(#{name}) AND (
        F.MBL_TELNO_ENCPT = C##RG.ENC_B64(#{phone1}) OR
        F.MBL_TELNO_ENCPT = C##RG.ENC_B64(#{phone2})
    )
    )
    )
AND (C.USER_CNTN_INTRCP_YN IS NULL OR C.USER_CNTN_INTRCP_YN = 'N')
AND C.USER_ID_USE_SE_CD IN ('1', '2')

mapper.update:
/* setPasswordTemporary - Lee JiSeob */
UPDATE SAA200 /* 사용자 */
SET USER_PSWD_ENCPT = C##RG.HASH_B64(#{pass}), LAST_MDFR_ID = #{userId}, LAST_MDFCN_DT = SYSDATE,
LGN_ERR_CONT = 0
WHERE USER_ID = #{userId}
AND (USER_CNTN_INTRCP_YN IS NULL OR USER_CNTN_INTRCP_YN = 'N') AND USER_ID_USE_SE_CD IN ('1', '2')

