/* deleteSessionExpireMessage - Lee JiSeob */

DELETE FROM SAB720 /* 세션 종료 메시지 */

WHERE 
    CNTN_IP_ADDR = #{IP}

mapper.select:
/* selectPrivacySchedule - Lee JiSeob */
SELECT
CASE WHEN NVL(MAX(FRST_REG_DT), SYSDATE - #{PRIVACY_RE_CONSENT_CYCLE} - 1) < (SYSDATE - #{PRIVACY_RE_CONSENT_CYCLE}) THEN 'Y' ELSE 'N' END
FROM SAA220 /* 회원 동의 내역 */
WHERE USER_ID = #{USER_ID}



/* selectChangePassword - Lee JiSeob */

SELECT

    COUNT(*)

FROM SAA200 /* 사용자 */

WHERE USER_ID = #{USER_ID}

AND NVL(PSWD_LAST_CHG_DT, SYSDATE - #{PASSWORD_CHANGE_CYCLE} - 1) < (SYSDATE - #{PASSWORD_CHANGE_CYCLE})
